-- PHASE 4 REHEARSAL (generated from supabase/rehearsal/rehearsal_phase4.template.sql + the two migrations by scripts/build-rehearsal.mjs; do not edit this file by hand).
-- ONE batch that applies 20261128090000_freeze_enforcement.sql and 20261128100000_own_claims_rpc.sql (phase 2, 20261126090000, is already live), exercises them on the private
-- test trip, then ENDS WITH AN ERROR so that EVERYTHING ROLLS BACK. The result is the final error message: "REHEARSAL PASS [...]" or "REHEARSAL FAIL [...]".
-- Impersonation is claims-only plus SET LOCAL ROLE authenticated (the technique that passed on live); the service role is claims only, never SET ROLE service_role.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';

CREATE TEMP TABLE _rehearsal (step text, ok boolean, detail text);
CREATE TEMP TABLE _rh_ctx (k text PRIMARY KEY, v text);
CREATE FUNCTION pg_temp.rh_rec(p_step text, p_ok boolean, p_detail text) RETURNS void LANGUAGE sql AS $f$
  INSERT INTO _rehearsal VALUES (p_step, coalesce(p_ok, false), left(p_detail, 400))
$f$;
CREATE FUNCTION pg_temp.rh_ctx(p_k text) RETURNS text LANGUAGE sql STABLE AS $f$
  SELECT v FROM _rh_ctx WHERE k = p_k
$f$;
CREATE FUNCTION pg_temp.rh_jwt(p_uid uuid) RETURNS void LANGUAGE plpgsql AS $f$
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', p_uid, 'role', 'authenticated')::text, true);
  PERFORM set_config('request.jwt.claim.sub', p_uid::text, true);
  PERFORM set_config('request.jwt.claim.role', 'authenticated', true);
END
$f$;
CREATE FUNCTION pg_temp.rh_svc() RETURNS void LANGUAGE plpgsql AS $f$
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('role', 'service_role')::text, true);
  PERFORM set_config('request.jwt.claim.sub', '', true);
  PERFORM set_config('request.jwt.claim.role', 'service_role', true);
END
$f$;
-- a PostgREST request header, as the API sets it
CREATE FUNCTION pg_temp.rh_header(p_build text) RETURNS void LANGUAGE plpgsql AS $f$
BEGIN
  PERFORM set_config('request.headers', json_build_object('x-client-info', p_build)::text, true);
END
$f$;

-- a real expense_splits row, whatever NOT NULL columns the live table has: an EXPLICIT column list (id, expense_id, user_id, amount, plus any NOT NULL column that has no default),
-- so every column with a default (created_at, split_type ...) gets its default. (Inserting a whole jsonb record would write NULL into the unlisted columns.)
CREATE FUNCTION pg_temp.rh_make_split(p_e uuid, p_u uuid) RETURNS void LANGUAGE plpgsql AS $f$
DECLARE
  c record; j jsonb := jsonb_build_object('id', gen_random_uuid(), 'expense_id', p_e, 'user_id', p_u, 'amount', 1); v_cols text;
BEGIN
  FOR c IN SELECT column_name, data_type, udt_name FROM information_schema.columns
           WHERE table_schema = 'public' AND table_name = 'expense_splits' AND is_nullable = 'NO' AND column_default IS NULL LOOP
    IF j ? c.column_name THEN CONTINUE; END IF;
    j := j || jsonb_build_object(c.column_name, CASE c.data_type
      WHEN 'uuid' THEN to_jsonb(gen_random_uuid()) WHEN 'numeric' THEN to_jsonb(0) WHEN 'integer' THEN to_jsonb(0) WHEN 'boolean' THEN to_jsonb(false)
      WHEN 'text' THEN to_jsonb('x'::text) WHEN 'timestamp with time zone' THEN to_jsonb(now())
      WHEN 'USER-DEFINED' THEN to_jsonb((SELECT e.enumlabel FROM pg_enum e JOIN pg_type t ON t.oid = e.enumtypid WHERE t.typname = c.udt_name ORDER BY e.enumsortorder LIMIT 1))
      ELSE to_jsonb('x'::text) END);
  END LOOP;
  SELECT string_agg(quote_ident(k), ', ') INTO v_cols FROM jsonb_object_keys(j) AS k WHERE EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'expense_splits' AND column_name = k);
  EXECUTE format('INSERT INTO public.expense_splits (%s) SELECT %s FROM jsonb_populate_record(NULL::public.expense_splits, $1)', v_cols, v_cols) USING j;
END
$f$;

-- ===== 0a. BEFORE the migrations: what is live is what the earlier migrations shipped; the new names are free ==============================================
DO $rh$
DECLARE
  v_o text; v_r text; v_n integer;
BEGIN
  BEGIN
    SELECT md5(prosrc) INTO v_o FROM pg_proc WHERE pronamespace = 'public'::regnamespace AND proname = 'guard_claim_overclaim';
    SELECT md5(prosrc) INTO v_r FROM pg_proc WHERE pronamespace = 'public'::regnamespace AND proname = '_receipt_resplit_table_items';
    PERFORM pg_temp.rh_rec('pre.bodies', v_o = '@@OVERCLAIM_MD5@@' AND v_r = '@@RESPLIT_MD5@@', format('guard_claim_overclaim md5=%s (want @@OVERCLAIM_MD5@@) _receipt_resplit_table_items md5=%s (want @@RESPLIT_MD5@@)', v_o, v_r));
    SELECT count(*) INTO v_n FROM pg_proc WHERE pronamespace = 'public'::regnamespace AND proname IN ('_trip_frozen_for_write', '_expense_frozen_for_write', 'guard_frozen_expense', 'guard_frozen_expense_child', 'guard_trip_settlement_columns', 'set_my_receipt_claims', '_log_client_direct_write', 'count_client_direct_write');
    PERFORM pg_temp.rh_rec('pre.names_free', v_n = 0 AND to_regclass('public.client_direct_writes') IS NULL
      AND NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname IN ('trg_guard_frozen_expense', 'trg_guard_frozen_split', 'trg_guard_frozen_line', 'trg_guard_frozen_claim_delete', 'trg_guard_trip_settlement_columns', 'trg_count_direct_claims', 'trg_count_direct_lines', 'trg_count_direct_splits')),
      'none of the phase-4 functions, triggers or the counter table exist yet');
    INSERT INTO _rh_ctx VALUES ('act0', (SELECT count(*) FROM public.activity_feed)::text), ('notif0', (SELECT count(*) FROM public.notifications)::text);
  EXCEPTION WHEN OTHERS THEN
    PERFORM pg_temp.rh_rec('pre', false, 'ERROR ' || SQLSTATE || ' ' || SQLERRM);
  END;
END
$rh$;

-- ===== BEGIN MIGRATION 1 (verbatim copy of supabase/migrations/20261128090000_freeze_enforcement.sql) =====
@@MIGRATION1@@
-- ===== END MIGRATION 1 =====
-- ===== BEGIN MIGRATION 2 (verbatim copy of supabase/migrations/20261128100000_own_claims_rpc.sql) =====
@@MIGRATION2@@
-- ===== END MIGRATION 2 =====

-- ===== 0. the test trip, the two people ==========================================================================================
DO $rh$
DECLARE
  v_trip constant uuid := 'be551bc4-a524-4b6a-a0c9-b74a7168ced4';
  v_a uuid; v_b uuid; v_name text; v_frozen boolean; v_n integer;
BEGIN
  BEGIN
    SELECT t.created_by, t.name, t.settlement_snapshot IS NOT NULL INTO v_a, v_name, v_frozen FROM public.trips t WHERE t.id = v_trip;
    IF NOT FOUND THEN
      PERFORM pg_temp.rh_rec('setup.trip', false, 'test trip be551bc4-... not found');
      RETURN;
    END IF;
    SELECT tp.user_id INTO v_b FROM public.trip_participants tp
     WHERE tp.trip_id = v_trip AND tp.user_id <> v_a AND coalesce(tp.active, true)
     ORDER BY public._settlement_can_manage(v_trip, tp.user_id), tp.user_id LIMIT 1;
    SELECT count(*) INTO v_n FROM public.trip_participants tp WHERE tp.trip_id = v_trip;
    INSERT INTO _rh_ctx VALUES ('trip', v_trip::text), ('a', v_a::text), ('b_manager', coalesce(public._settlement_can_manage(v_trip, v_b), false)::text);
    IF v_b IS NOT NULL THEN INSERT INTO _rh_ctx VALUES ('b', v_b::text); END IF;
    UPDATE public.trips SET settlement_snapshot = NULL WHERE id = v_trip;   -- as the OWNER (not a client): unfrozen for the first half; rolled back with everything
    PERFORM pg_temp.rh_rec('setup.trip', v_a IS NOT NULL AND v_b IS NOT NULL, format('name=%s participants=%s was_frozen=%s', v_name, v_n, v_frozen));
  EXCEPTION WHEN OTHERS THEN
    PERFORM pg_temp.rh_rec('setup.trip', false, 'ERROR ' || SQLSTATE || ' ' || SQLERRM);
  END;
END
$rh$;

-- ===== 1. structure ===========================================================================================================================
DO $rh$
DECLARE
  v_txt text; v_bad text := ''; r record;
BEGIN
  BEGIN
    SELECT string_agg(x.t || '.' || x.n, ',') INTO v_txt FROM (VALUES
      ('expenses', 'trg_guard_frozen_expense'), ('expense_splits', 'trg_guard_frozen_split'), ('expense_line_items', 'trg_guard_frozen_line'), ('expense_item_claims', 'trg_guard_frozen_claim_delete'),
      ('trips', 'trg_guard_trip_settlement_columns'), ('expense_item_claims', 'trg_count_direct_claims'), ('expense_line_items', 'trg_count_direct_lines'), ('expense_splits', 'trg_count_direct_splits')) x(t, n)
     WHERE NOT EXISTS (SELECT 1 FROM pg_trigger g WHERE g.tgrelid = ('public.' || x.t)::regclass AND g.tgname = x.n AND NOT g.tgisinternal AND g.tgenabled = 'O');
    PERFORM pg_temp.rh_rec('struct.triggers', v_txt IS NULL, coalesce('missing/disabled: ' || v_txt, '8 new triggers enabled'));
    PERFORM pg_temp.rh_rec('struct.response_policies', (SELECT array_agg(cmd ORDER BY cmd) FROM pg_policies WHERE tablename = 'expense_claim_responses') = ARRAY['SELECT']
      AND NOT has_table_privilege('authenticated', 'public.expense_claim_responses', 'INSERT'), 'only the SELECT policy is left; no INSERT privilege for authenticated');
    FOR r IN SELECT * FROM (VALUES
      ('public._trip_frozen_for_write(uuid)', false, true),
      ('public._expense_frozen_for_write(uuid)', false, true),
      ('public.set_my_receipt_claims(uuid,jsonb)', false, true),
      ('public._log_client_direct_write(text,text)', false, true),
      ('public.guard_frozen_expense()', false, false),
      ('public.guard_frozen_expense_child()', false, false),
      ('public.guard_trip_settlement_columns()', false, false),
      ('public.count_client_direct_write()', false, false),
      ('public._receipt_resplit_table_items(uuid)', false, false)
    ) AS x(f, want_anon, want_auth) LOOP
      IF has_function_privilege('anon', r.f, 'EXECUTE') IS DISTINCT FROM r.want_anon OR has_function_privilege('authenticated', r.f, 'EXECUTE') IS DISTINCT FROM r.want_auth THEN
        v_bad := v_bad || r.f || ' ';
      END IF;
    END LOOP;
    IF has_table_privilege('authenticated', 'public.client_direct_writes', 'SELECT') THEN v_bad := v_bad || 'client_direct_writes-readable '; END IF;
    PERFORM pg_temp.rh_rec('struct.privileges', v_bad = '', CASE WHEN v_bad = '' THEN '8 functions + the counter table: as intended' ELSE 'wrong: ' || v_bad END);
  EXCEPTION WHEN OTHERS THEN
    PERFORM pg_temp.rh_rec('struct', false, 'ERROR ' || SQLSTATE || ' ' || SQLERRM);
  END;
END
$rh$;

-- ===== 2. UNFROZEN: normal work, set_my_receipt_claims (server amounts), the direct-write counter ====================================================
DO $rh$
DECLARE
  v_trip uuid := pg_temp.rh_ctx('trip')::uuid; v_a uuid := pg_temp.rh_ctx('a')::uuid; v_b uuid := pg_temp.rh_ctx('b')::uuid;
  v_e uuid; v_l1 uuid; v_l2 uuid; v_x uuid; v_r jsonb; v_hint text; v_n integer; v_amt numeric; v_sum numeric;
BEGIN
  IF v_a IS NULL OR v_b IS NULL THEN PERFORM pg_temp.rh_rec('unfrozen', false, 'no test trip / people'); RETURN; END IF;
  BEGIN
    PERFORM pg_temp.rh_jwt(v_a);
    SET LOCAL ROLE authenticated;
    INSERT INTO public.expenses (trip_id, paid_by, amount, currency, description, status, ai_parsed, participant_ids)
    VALUES (v_trip, v_a, 40.01, 'GBP', 'REHEARSAL phase 4 receipt (rolled back)', 'unallocated', true, ARRAY[v_a, v_b]) RETURNING id INTO v_e;
    INSERT INTO public.expense_line_items (expense_id, line_number, name_original, quantity, unit_price, subtotal, total_amount) VALUES (v_e, 1, 'beers x3', 3, 3.33, 10.01, 10.01) RETURNING id INTO v_l1;
    INSERT INTO public.expense_line_items (expense_id, line_number, name_original, quantity, unit_price, subtotal, total_amount) VALUES (v_e, 2, 'pizza', 1, 30, 30, 30) RETURNING id INTO v_l2;
    RESET ROLE;
    INSERT INTO _rh_ctx VALUES ('e', v_e::text), ('l1', v_l1::text), ('l2', v_l2::text);
    PERFORM pg_temp.rh_rec('unfrozen.client_can_create', true, 'GBP 40.01: beers 10.01 (3 units) + pizza 30.00');
  EXCEPTION WHEN OTHERS THEN
    RESET ROLE;
    PERFORM pg_temp.rh_rec('unfrozen.client_can_create', false, 'ERROR ' || SQLSTATE || ' ' || SQLERRM);
    RETURN;
  END;
  -- server-computed amounts: A, B and A again take the three beers; the last one takes what is left (3.35 | 3.33 | 3.33 = 10.01 or similar, exactly the line)
  BEGIN
    PERFORM pg_temp.rh_jwt(v_a);
    SET LOCAL ROLE authenticated;
    v_r := public.set_my_receipt_claims(v_e, jsonb_build_array(jsonb_build_object('line_item_id', v_l1, 'quantity', 2)));
    RESET ROLE;
    PERFORM pg_temp.rh_jwt(v_b);
    SET LOCAL ROLE authenticated;
    v_r := public.set_my_receipt_claims(v_e, jsonb_build_array(jsonb_build_object('line_item_id', v_l1, 'quantity', 1)));
    RESET ROLE;
    SELECT sum(amount_owed), count(*) INTO v_sum, v_n FROM public.expense_item_claims WHERE line_item_id = v_l1;
    SELECT amount_owed INTO v_amt FROM public.expense_item_claims WHERE line_item_id = v_l1 AND user_id = v_a;
    PERFORM pg_temp.rh_rec('own_claims.server_amounts', v_sum = 10.01 AND v_n = 2 AND v_amt = 6.67 AND (v_r #>> '{lines,0,unclaimed}')::numeric = 0,
      format('line total 10.01 claimed %s over %s rows (A 2 units = %s, B takes the last unit); result unclaimed=%s', v_sum, v_n, v_amt, v_r #>> '{lines,0,unclaimed}'));
  EXCEPTION WHEN OTHERS THEN
    RESET ROLE;
    PERFORM pg_temp.rh_rec('own_claims.server_amounts', false, 'ERROR ' || SQLSTATE || ' ' || SQLERRM);
  END;
  BEGIN
    PERFORM pg_temp.rh_jwt(v_b);
    SET LOCAL ROLE authenticated;
    PERFORM public.set_my_receipt_claims(v_e, jsonb_build_array(jsonb_build_object('line_item_id', v_l1, 'quantity', 2)));
    RESET ROLE;
    PERFORM pg_temp.rh_rec('own_claims.overclaim_refused', false, 'NOT refused');
  EXCEPTION WHEN OTHERS THEN
    RESET ROLE;
    GET STACKED DIAGNOSTICS v_hint = PG_EXCEPTION_HINT;
    PERFORM pg_temp.rh_rec('own_claims.overclaim_refused', v_hint = 'overclaimed', SQLSTATE || ' hint=' || coalesce(v_hint, ''));
  END;
  -- the counter: a DIRECT client write (an old build) is logged with its build tag; an RPC write is not
  BEGIN
    DELETE FROM public.client_direct_writes;
    PERFORM pg_temp.rh_header('supabase-js-web/2.78.0');
    PERFORM pg_temp.rh_jwt(v_b);
    SET LOCAL ROLE authenticated;
    INSERT INTO public.expense_item_claims (line_item_id, user_id, expense_id, quantity_claimed, amount_owed) VALUES (v_l2, v_b, v_e, 1, 30);
    PERFORM public.set_my_receipt_claims(v_e, jsonb_build_array(jsonb_build_object('line_item_id', v_l2, 'quantity', 0)));
    RESET ROLE;
    SELECT count(*) INTO v_n FROM public.client_direct_writes WHERE tbl = 'expense_item_claims' AND op = 'INSERT' AND build = 'supabase-js-web/2.78.0' AND user_id = v_b;
    PERFORM pg_temp.rh_rec('counter.direct_write_logged_rpc_not', v_n = 1 AND (SELECT count(*) FROM public.client_direct_writes) = 1, format('direct INSERT rows with the build tag: %s; total log rows: %s (the RPC write is not logged)', v_n, (SELECT count(*) FROM public.client_direct_writes)));
    PERFORM set_config('request.headers', '', true);
  EXCEPTION WHEN OTHERS THEN
    RESET ROLE;
    PERFORM pg_temp.rh_rec('counter.direct_write_logged_rpc_not', false, 'ERROR ' || SQLSTATE || ' ' || SQLERRM);
  END;
END
$rh$;

-- ===== 3. FROZEN: refusals, then what stays allowed ==========================================================================================
DO $rh$
DECLARE
  v_trip uuid := pg_temp.rh_ctx('trip')::uuid; v_a uuid := pg_temp.rh_ctx('a')::uuid; v_b uuid := pg_temp.rh_ctx('b')::uuid; v_e uuid := pg_temp.rh_ctx('e')::uuid;
  v_l1 uuid := pg_temp.rh_ctx('l1')::uuid; v_hint text; v_n integer; v_before integer; v_sp integer;
  v_cases text[][] := ARRAY[
    ['expense INSERT', 'b', 'INSERT INTO public.expenses (trip_id, paid_by, amount, description) VALUES (''%trip%'', ''%b%'', 5, ''x'')'],
    ['amount UPDATE', 'a', 'UPDATE public.expenses SET amount = amount + 1 WHERE id = ''%e%'''],
    ['paid_by UPDATE', 'a', 'UPDATE public.expenses SET paid_by = ''%b%'' WHERE id = ''%e%'''],
    ['expense DELETE', 'a', 'DELETE FROM public.expenses WHERE id = ''%e%'''],
    ['splits INSERT', 'a', 'INSERT INTO public.expense_splits (expense_id, user_id, amount) VALUES (''%e%'', ''%b%'', 1)'],
    ['line item INSERT', 'a', 'INSERT INTO public.expense_line_items (expense_id, line_number, name_original, quantity, unit_price, subtotal, total_amount) VALUES (''%e%'', 9, ''x'', 1, 1, 1, 1)'],
    ['line item DELETE', 'a', 'DELETE FROM public.expense_line_items WHERE id = ''%l1%'''],
    ['claim DELETE', 'b', 'DELETE FROM public.expense_item_claims WHERE expense_id = ''%e%'' AND user_id = ''%b%'''],
    ['claim INSERT', 'b', 'INSERT INTO public.expense_item_claims (line_item_id, user_id, expense_id, quantity_claimed, amount_owed) VALUES (''%l1%'', ''%b%'', ''%e%'', 0.01, 0.01)']
  ];
  v_i integer; v_sql text; v_who uuid; v_s uuid;
BEGIN
  IF v_e IS NULL THEN PERFORM pg_temp.rh_rec('frozen', false, 'no test expense'); RETURN; END IF;
  UPDATE public.trips SET settlement_snapshot = jsonb_build_object('transactions', '[]'::jsonb) WHERE id = v_trip;     -- as the owner: freezes the test trip inside the transaction
  SELECT count(*) INTO v_before FROM public.expense_item_claims WHERE expense_id = v_e;
  FOR v_i IN 1..array_length(v_cases, 1) LOOP
    v_sql := replace(replace(replace(replace(v_cases[v_i][3], '%trip%', v_trip::text), '%b%', v_b::text), '%e%', v_e::text), '%l1%', v_l1::text);
    v_who := CASE v_cases[v_i][2] WHEN 'a' THEN v_a ELSE v_b END;
    BEGIN
      PERFORM pg_temp.rh_jwt(v_who);
      SET LOCAL ROLE authenticated;
      EXECUTE v_sql;
      RESET ROLE;
      PERFORM pg_temp.rh_rec('frozen.refused: ' || v_cases[v_i][1], false, 'NOT refused');
    EXCEPTION WHEN OTHERS THEN
      RESET ROLE;
      GET STACKED DIAGNOSTICS v_hint = PG_EXCEPTION_HINT;
      PERFORM pg_temp.rh_rec('frozen.refused: ' || v_cases[v_i][1], v_hint = 'frozen', SQLSTATE || ' hint=' || coalesce(v_hint, '') || ' ' || left(SQLERRM, 80));
    END;
  END LOOP;
  SELECT count(*) INTO v_n FROM public.expense_item_claims WHERE expense_id = v_e;
  PERFORM pg_temp.rh_rec('frozen.nothing_lost', v_n = v_before AND (SELECT count(*) FROM public.expense_line_items WHERE expense_id = v_e) = 2, format('claims before %s after %s; lines still 2 (the old claim page''s delete-then-insert stops at the delete)', v_before, v_n));
  -- splits UPDATE / DELETE need a real row: create one (owner, trip unfrozen for that instant), then freeze again
  BEGIN
    UPDATE public.trips SET settlement_snapshot = NULL WHERE id = v_trip;
    PERFORM pg_temp.rh_make_split(v_e, v_b);
    UPDATE public.trips SET settlement_snapshot = jsonb_build_object('transactions', '[]'::jsonb) WHERE id = v_trip;
    SELECT count(*) INTO v_sp FROM public.expense_splits WHERE expense_id = v_e;
    PERFORM pg_temp.rh_rec('frozen.setup_split_row', v_sp = 1, 'split rows created: ' || v_sp);
  EXCEPTION WHEN OTHERS THEN
    PERFORM pg_temp.rh_rec('frozen.setup_split_row', false, 'ERROR ' || SQLSTATE || ' ' || SQLERRM);
  END;
  FOR v_i IN 1..2 LOOP
    BEGIN
      PERFORM pg_temp.rh_jwt(v_a);
      SET LOCAL ROLE authenticated;
      IF v_i = 1 THEN
        UPDATE public.expense_splits SET amount = amount + 1 WHERE expense_id = v_e;
      ELSE
        DELETE FROM public.expense_splits WHERE expense_id = v_e;
      END IF;
      GET DIAGNOSTICS v_n = ROW_COUNT;
      RESET ROLE;
      PERFORM pg_temp.rh_rec('frozen.refused: splits ' || CASE v_i WHEN 1 THEN 'UPDATE' ELSE 'DELETE' END, false, 'NOT refused (rows=' || v_n || ')');
    EXCEPTION WHEN OTHERS THEN
      RESET ROLE;
      GET STACKED DIAGNOSTICS v_hint = PG_EXCEPTION_HINT;
      PERFORM pg_temp.rh_rec('frozen.refused: splits ' || CASE v_i WHEN 1 THEN 'UPDATE' ELSE 'DELETE' END, v_hint = 'frozen', SQLSTATE || ' hint=' || coalesce(v_hint, ''));
    END;
  END LOOP;
  -- the receipt RPCs
  BEGIN
    PERFORM pg_temp.rh_jwt(v_b);
    SET LOCAL ROLE authenticated;
    PERFORM public.set_my_receipt_claims(v_e, jsonb_build_array(jsonb_build_object('line_item_id', v_l1, 'quantity', 0)));
    RESET ROLE;
    PERFORM pg_temp.rh_rec('frozen.refused: set_my_receipt_claims', false, 'NOT refused');
  EXCEPTION WHEN OTHERS THEN
    RESET ROLE;
    GET STACKED DIAGNOSTICS v_hint = PG_EXCEPTION_HINT;
    PERFORM pg_temp.rh_rec('frozen.refused: set_my_receipt_claims', v_hint = 'frozen', SQLSTATE || ' hint=' || coalesce(v_hint, ''));
  END;
  BEGIN
    PERFORM pg_temp.rh_jwt(v_b);
    SET LOCAL ROLE authenticated;
    INSERT INTO public.expense_claim_responses (expense_id, user_id, response) VALUES (v_e, v_b, 'done');
    RESET ROLE;
    PERFORM pg_temp.rh_rec('frozen.response_direct_write_gone', false, 'NOT refused');
  EXCEPTION WHEN OTHERS THEN
    RESET ROLE;
    PERFORM pg_temp.rh_rec('frozen.response_direct_write_gone', SQLSTATE = '42501', SQLSTATE || ' ' || left(SQLERRM, 80));
  END;
  -- allowed while frozen: cosmetic edits
  BEGIN
    PERFORM pg_temp.rh_jwt(v_a);
    SET LOCAL ROLE authenticated;
    UPDATE public.expenses SET description = 'REHEARSAL renamed while frozen', receipt_url = 'rehearsal.jpg' WHERE id = v_e;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    RESET ROLE;
    PERFORM pg_temp.rh_rec('frozen.allowed: cosmetic edit', v_n = 1 AND (SELECT description FROM public.expenses WHERE id = v_e) = 'REHEARSAL renamed while frozen', 'rows=' || v_n);
  EXCEPTION WHEN OTHERS THEN
    RESET ROLE;
    PERFORM pg_temp.rh_rec('frozen.allowed: cosmetic edit', false, 'ERROR ' || SQLSTATE || ' ' || SQLERRM);
  END;
  -- the snapshot is written only by the RPCs
  BEGIN
    PERFORM pg_temp.rh_jwt(v_a);
    SET LOCAL ROLE authenticated;
    UPDATE public.trips SET settlement_snapshot = NULL WHERE id = v_trip;
    RESET ROLE;
    PERFORM pg_temp.rh_rec('frozen.trips_snapshot_use_rpc', false, 'NOT refused');
  EXCEPTION WHEN OTHERS THEN
    RESET ROLE;
    GET STACKED DIAGNOSTICS v_hint = PG_EXCEPTION_HINT;
    PERFORM pg_temp.rh_rec('frozen.trips_snapshot_use_rpc', v_hint = 'use_rpc', SQLSTATE || ' hint=' || coalesce(v_hint, ''));
  END;
  -- the service key and the definer RPCs are not clients
  BEGIN
    PERFORM pg_temp.rh_svc();
    UPDATE public.expenses SET amount = amount WHERE id = v_e;
    PERFORM pg_temp.rh_rec('frozen.allowed: service role write', true, 'ok');
  EXCEPTION WHEN OTHERS THEN
    PERFORM pg_temp.rh_rec('frozen.allowed: service role write', false, 'ERROR ' || SQLSTATE || ' ' || SQLERRM);
  END;
  -- settlements while frozen: the payer marks one paid, the receiver confirms it (created by the organiser, as the freeze would)
  BEGIN
    PERFORM pg_temp.rh_jwt(v_a);
    SET LOCAL ROLE authenticated;
    INSERT INTO public.settlements (trip_id, from_user_id, to_user_id, amount, currency, status, created_by, settled_at) VALUES (v_trip, v_b, v_a, 1.00, 'GBP', 'suggested', v_a, now()) RETURNING id INTO v_s;
    RESET ROLE;
    PERFORM pg_temp.rh_jwt(v_b);
    SET LOCAL ROLE authenticated;
    UPDATE public.settlements SET status = 'marked_paid' WHERE id = v_s;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    RESET ROLE;
    PERFORM pg_temp.rh_rec('frozen.allowed: mark a payment paid', v_n = 1 AND (SELECT status FROM public.settlements WHERE id = v_s) = 'marked_paid', 'rows=' || v_n);
    PERFORM pg_temp.rh_jwt(v_a);
    SET LOCAL ROLE authenticated;
    UPDATE public.settlements SET status = 'confirmed' WHERE id = v_s;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    RESET ROLE;
    PERFORM pg_temp.rh_rec('frozen.allowed: confirm a payment', v_n = 1 AND (SELECT status FROM public.settlements WHERE id = v_s) = 'confirmed', 'rows=' || v_n);
  EXCEPTION WHEN OTHERS THEN
    RESET ROLE;
    PERFORM pg_temp.rh_rec('frozen.allowed: mark / confirm a payment', false, 'ERROR ' || SQLSTATE || ' ' || SQLERRM);
  END;
  -- unfreeze by the organiser (the real RPC), and money edits work again
  BEGIN
    PERFORM pg_temp.rh_jwt(v_a);
    SET LOCAL ROLE authenticated;
    PERFORM public.unfreeze_settlements(v_trip);
    UPDATE public.expenses SET amount = amount WHERE id = v_e;
    RESET ROLE;
    PERFORM pg_temp.rh_rec('frozen.allowed: unfreeze', (SELECT settlement_snapshot IS NULL FROM public.trips WHERE id = v_trip), 'unfreeze_settlements by the organiser works; the expense is editable again');
  EXCEPTION WHEN OTHERS THEN
    RESET ROLE;
    PERFORM pg_temp.rh_rec('frozen.allowed: unfreeze', false, 'ERROR ' || SQLSTATE || ' ' || SQLERRM);
  END;
END
$rh$;

-- ===== 4. a throwaway FROZEN trip is deleted by its creator: the cascades run as the owner, through every guard ======================================
DO $rh$
DECLARE
  v_trip uuid := pg_temp.rh_ctx('trip')::uuid; v_a uuid := pg_temp.rh_ctx('a')::uuid; v_bb uuid := pg_temp.rh_ctx('b')::uuid; v_new uuid := gen_random_uuid(); v_x uuid; v_n integer;
BEGIN
  BEGIN
    INSERT INTO public.trips SELECT (jsonb_populate_record(NULL::public.trips, to_jsonb(t) || jsonb_build_object('id', v_new, 'name', 'REHEARSAL throwaway (rolled back)'))).* FROM public.trips t WHERE t.id = v_trip;
    INSERT INTO public.expenses (trip_id, paid_by, amount, currency, description) VALUES (v_new, v_a, 5, 'GBP', 'REHEARSAL throwaway expense') RETURNING id INTO v_x;
    UPDATE public.trips SET settlement_snapshot = jsonb_build_object('transactions', '[]'::jsonb) WHERE id = v_new;
    -- removing a participant on the frozen throwaway trip (the creator is its organiser): copy the two participant rows, then delete B's as the organiser
    INSERT INTO public.trip_participants SELECT (jsonb_populate_record(NULL::public.trip_participants, to_jsonb(p) || jsonb_build_object('trip_id', v_new))).* FROM public.trip_participants p WHERE p.trip_id = v_trip AND p.user_id IN (v_a, v_bb);
    PERFORM pg_temp.rh_jwt(v_a);
    SET LOCAL ROLE authenticated;
    DELETE FROM public.trip_participants WHERE trip_id = v_new AND user_id = v_bb;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    RESET ROLE;
    PERFORM pg_temp.rh_rec('frozen.allowed: remove a participant', v_n = 1, 'participant rows removed by the organiser: ' || v_n);
    PERFORM pg_temp.rh_jwt(v_a);
    SET LOCAL ROLE authenticated;
    DELETE FROM public.trips WHERE id = v_new;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    RESET ROLE;
    PERFORM pg_temp.rh_rec('frozen.trip_delete_cascades', v_n = 1 AND NOT EXISTS (SELECT 1 FROM public.expenses WHERE id = v_x), format('trip rows deleted=%s, its expense gone=%s (if 0 rows: the trips DELETE policy does not let the creator in; then only the cascade check is skipped)', v_n, NOT EXISTS (SELECT 1 FROM public.expenses WHERE id = v_x)));
  EXCEPTION WHEN OTHERS THEN
    RESET ROLE;
    PERFORM pg_temp.rh_rec('frozen.trip_delete_cascades', false, 'ERROR ' || SQLSTATE || ' ' || SQLERRM);
  END;
END
$rh$;

-- ===== 5. table-item share activity: "I wasn't there" moves the bread, A's share goes up, an activity row, no notification =========================
DO $rh$
DECLARE
  v_trip uuid := pg_temp.rh_ctx('trip')::uuid; v_a uuid := pg_temp.rh_ctx('a')::uuid; v_b uuid := pg_temp.rh_ctx('b')::uuid; v_e uuid; v_l uuid; v_l2 uuid; v_n integer;
BEGIN
  IF v_a IS NULL OR v_b IS NULL THEN RETURN; END IF;
  BEGIN
    INSERT INTO public.expenses (trip_id, paid_by, amount, currency, description, status, ai_parsed, participant_ids)
    VALUES (v_trip, v_a, 30.00, 'GBP', 'REHEARSAL table activity (rolled back)', 'unallocated', true, ARRAY[v_a, v_b]) RETURNING id INTO v_e;
    INSERT INTO public.expense_line_items (expense_id, line_number, name_original, quantity, unit_price, subtotal, total_amount) VALUES (v_e, 1, 'bread', 1, 9, 9, 9) RETURNING id INTO v_l;
    INSERT INTO public.expense_line_items (expense_id, line_number, name_original, quantity, unit_price, subtotal, total_amount) VALUES (v_e, 2, 'main', 1, 21, 21, 21) RETURNING id INTO v_l2;
    PERFORM pg_temp.rh_jwt(v_a);
    SET LOCAL ROLE authenticated;
    PERFORM public.set_receipt_claims(v_e, jsonb_build_array(jsonb_build_object('line_item_id', v_l, 'shared_by_all', true), jsonb_build_object('line_item_id', v_l2, 'user_ids', jsonb_build_array(v_a))));
    RESET ROLE;
    PERFORM pg_temp.rh_jwt(v_b);
    SET LOCAL ROLE authenticated;
    PERFORM public.respond_to_receipt(v_e, 'not_there');
    RESET ROLE;
    SELECT count(*) INTO v_n FROM public.activity_feed WHERE verb = 'receipt_table_share_changed' AND entity ->> 'id' = v_e::text AND metadata ->> 'user_id' = v_a::text
      AND (metadata ->> 'from')::numeric = 4.50 AND (metadata ->> 'to')::numeric = 9.00;
    PERFORM pg_temp.rh_rec('activity.table_share_went_up', v_n = 1 AND (SELECT count(*) FROM public.notifications) = pg_temp.rh_ctx('notif0')::integer,
      format('activity rows for A (4.50 -> 9.00): %s; notifications unchanged', v_n));
  EXCEPTION WHEN OTHERS THEN
    RESET ROLE;
    PERFORM pg_temp.rh_rec('activity.table_share_went_up', false, 'ERROR ' || SQLSTATE || ' ' || SQLERRM);
  END;
END
$rh$;

-- ===== FINAL: report through the error message (this also rolls everything back) ===============================================================================
DO $rh$
DECLARE
  v_all boolean; v_json text; v_failed integer; v_total integer;
BEGIN
  SELECT coalesce(bool_and(ok), false), count(*) FILTER (WHERE NOT ok), count(*) INTO v_all, v_failed, v_total FROM _rehearsal;
  SELECT coalesce(jsonb_agg(jsonb_build_object('step', step, 'ok', ok, 'detail', left(detail, 160)) ORDER BY ok, ctid), '[]'::jsonb)::text INTO v_json FROM _rehearsal;
  IF length(v_json) > 6000 THEN
    SELECT coalesce(jsonb_agg(jsonb_build_object('step', step, 'ok', ok, 'detail', left(detail, CASE WHEN ok THEN 0 ELSE 90 END)) ORDER BY ok, ctid), '[]'::jsonb)::text INTO v_json FROM _rehearsal;
  END IF;
  IF length(v_json) > 6000 THEN
    SELECT coalesce(jsonb_agg(jsonb_build_object('step', step, 'ok', ok, 'detail', left(detail, 90)) ORDER BY ok, ctid), '[]'::jsonb)::text INTO v_json FROM _rehearsal WHERE NOT ok;
    v_json := left(v_json, 5800) || ' (only failing steps shown)';
  END IF;
  RAISE EXCEPTION '%', 'REHEARSAL ' || CASE WHEN v_all THEN 'PASS' ELSE 'FAIL' END || ' (' || v_total || ' steps, ' || v_failed || ' failed) ' || v_json;
END
$rh$;
ROLLBACK;
